static void startAdvertising() {
    bool ok = NimBLEDevice::startAdvertising();
    Serial.printf("[BLE] advertising started as \"%s\": %s\n", GLASSES_DEVICE_NAME, ok ? "ok" : "FAILED");
}

class ServerCallbacks : public NimBLEServerCallbacks {
    void onConnect(NimBLEServer* s, NimBLEConnInfo& info) override {
        isConnected = true;
        connHandle = info.getConnHandle();
        Serial.printf("[BLE] client connected: %s\n", info.getAddress().toString().c_str());
        // 7.5-15 ms interval for throughput; supervision timeout 4 s.
        s->updateConnParams(info.getConnHandle(), 6, 12, 0, 400);
    }
    void onDisconnect(NimBLEServer*, NimBLEConnInfo&, int reason) override {
        isConnected = false;
        connHandle = BLE_HS_CONN_HANDLE_NONE;
        controlSub = imageSub = eventSub = audioUpSub = false;
        peerMtu = 23;
        xSemaphoreGive(indicationDone);  // unblock a transfer that was waiting on an ACK
        Serial.printf("[BLE] client disconnected (reason 0x%02x)\n", reason);
        startAdvertising();
    }
    void onMTUChange(uint16_t mtu, NimBLEConnInfo&) override {
        peerMtu = mtu;
        Serial.printf("[BLE] MTU negotiated: %u\n", mtu);
    }
    void onPhyUpdate(NimBLEConnInfo&, uint8_t tx, uint8_t rx) override {
        Serial.printf("[BLE] PHY now tx %u rx %u (1 = 1M, 2 = 2M, 3 = coded)\n", tx, rx);
    }
};

class SubscribeCallbacks : public NimBLECharacteristicCallbacks {
   public:
    void onStatus(NimBLECharacteristic* c, NimBLEConnInfo&, int code) override {
        // Only indications wait for this (ACK = BLE_HS_EDONE).
        if (c == controlChar || c == imageChar) {
            indicationStatus = code;
            xSemaphoreGive(indicationDone);
        }
    }
    void onSubscribe(NimBLECharacteristic* c, NimBLEConnInfo&, uint16_t v) override {
        bool on = v != 0;
        const char* name = "?";
        if (c == controlChar) { controlSub = on; name = "CONTROL"; }
        else if (c == imageChar) { imageSub = on; name = "IMAGE_DATA"; }
        else if (c == eventChar) { eventSub = on; name = "EVENT"; }
        else if (c == audioUpChar) { audioUpSub = on; name = "AUDIO_UP"; }
        Serial.printf("[BLE] %s subscription: %u\n", name, v);
    }
};

class ResultCallbacks : public NimBLECharacteristicCallbacks {
    void onWrite(NimBLECharacteristic* c, NimBLEConnInfo&) override {
        std::string text = c->getValue();
        Serial.printf("[BLE] RESULT_TEXT received (%u bytes): \"%s\"\n", (unsigned)text.size(), text.c_str());
    }
};

class CommandCallbacks : public NimBLECharacteristicCallbacks {
    void onWrite(NimBLECharacteristic* c, NimBLEConnInfo&) override {
        const std::string v = c->getValue();
        if (v.empty()) return;
        if ((uint8_t)v[0] == CMD_ABORT_IMAGE) abortImage = true;  // act now, not after the transfer
        Cmd cmd;
        cmd.len = (uint8_t)min(v.size(), sizeof(cmd.data));
        memcpy(cmd.data, v.data(), cmd.len);
        if (xQueueSend(cmdQ, &cmd, 0) != pdTRUE) Serial.println("[BLE] command queue full, dropped");
    }
};

class AudioDownCallbacks : public NimBLECharacteristicCallbacks {
    void onWrite(NimBLECharacteristic* c, NimBLEConnInfo&) override {
        const NimBLEAttValue& v = c->getValue();
        if (audioDown) audioDown(v.data(), v.size());
    }
};

void begin(AudioDownFn onAudioDown) {
    audioDown = onAudioDown;
    indicationDone = xSemaphoreCreateBinary();
    cmdQ = xQueueCreate(16, sizeof(Cmd));
    NimBLEDevice::init(GLASSES_DEVICE_NAME);
    NimBLEDevice::setPower(9);  // dBm
    NimBLEDevice::setMTU(GLASSES_MAX_MTU);

    server = NimBLEDevice::createServer();
    server->setCallbacks(new ServerCallbacks());

    auto* sub = new SubscribeCallbacks();
    NimBLEService* svc = server->createService(SERVICE_UUID);
    controlChar = svc->createCharacteristic(CONTROL_UUID, NIMBLE_PROPERTY::INDICATE);
    imageChar = svc->createCharacteristic(IMAGE_DATA_UUID, NIMBLE_PROPERTY::INDICATE);
    resultChar = svc->createCharacteristic(RESULT_TEXT_UUID, NIMBLE_PROPERTY::WRITE | NIMBLE_PROPERTY::WRITE_NR);
    commandChar = svc->createCharacteristic(COMMAND_UUID, NIMBLE_PROPERTY::WRITE);
    eventChar = svc->createCharacteristic(EVENT_UUID, NIMBLE_PROPERTY::NOTIFY);
    audioUpChar = svc->createCharacteristic(AUDIO_UP_UUID, NIMBLE_PROPERTY::NOTIFY);
    audioDownChar = svc->createCharacteristic(AUDIO_DOWN_UUID, NIMBLE_PROPERTY::WRITE_NR | NIMBLE_PROPERTY::WRITE);
    controlChar->setCallbacks(sub);
    imageChar->setCallbacks(sub);
    eventChar->setCallbacks(sub);
    audioUpChar->setCallbacks(sub);
    resultChar->setCallbacks(new ResultCallbacks());
    commandChar->setCallbacks(new CommandCallbacks());
    audioDownChar->setCallbacks(new AudioDownCallbacks());

    NimBLEAdvertising* adv = NimBLEDevice::getAdvertising();
    adv->setName(GLASSES_DEVICE_NAME);
    adv->addServiceUUID(SERVICE_UUID);
    adv->enableScanResponse(true);
    startAdvertising();
}

bool connected() { return isConnected; }
bool imagesReady() { return isConnected && controlSub && imageSub; }
uint16_t mtu() { return peerMtu; }
size_t maxPayload() { return min((size_t)(peerMtu > 3 ? peerMtu - 3 : 20), MAX_CHUNK_BYTES); }

bool sendEvent(uint8_t type, const uint8_t* payload, size_t len) {
    if (!isConnected || !eventSub) return false;
    uint8_t buf[64];
    size_t n = evt_prefix(buf, type, millis());
    if (len > sizeof(buf) - n) len = sizeof(buf) - n;
    if (len) memcpy(buf + n, payload, len);
    for (int attempt = 0; attempt < 5; attempt++) {
        if (eventChar->notify(buf, n + len)) return true;
        delay(5);  // out of mbufs: let the stack drain
    }
    Serial.printf("[BLE] event 0x%02x dropped (no buffers)\n", type);
    return false;
}

bool notifyAudio(const uint8_t* frame, size_t len, uint16_t* retries) {
    if (!isConnected || !audioUpSub) return false;
    for (int attempt = 0; attempt < 50; attempt++) {
        if (audioUpChar->notify(frame, len)) return true;
        if (retries) (*retries)++;
        delay(2);
    }
    return false;
}

/** Sends one indication and blocks until the phone acknowledges it. */
static bool indicateAndWait(NimBLECharacteristic* c, const uint8_t* data, size_t len) {
    xSemaphoreTake(indicationDone, 0);  // clear any stale signal
    if (!isConnected) return false;
    if (!c->indicate(data, len)) {
        Serial.printf("[BLE] indicate(%u B) refused by the BLE stack\n", (unsigned)len);
        return false;
    }
    if (xSemaphoreTake(indicationDone, pdMS_TO_TICKS(INDICATION_ACK_TIMEOUT_MS)) != pdTRUE) {
        Serial.printf("[BLE] no ACK from phone for a %u B indication within %lu ms\n",
                      (unsigned)len, (unsigned long)INDICATION_ACK_TIMEOUT_MS);
        return false;
    }
    if (indicationStatus != BLE_HS_EDONE) {
        Serial.printf("[BLE] %u B indication failed, status %d\n", (unsigned)len, indicationStatus);
        return false;
    }
    return isConnected;
}

bool sendImage(const camera::Shot& shot, uint8_t flags, bool viaNotify) {
    abortImage = false;
    if (viaNotify && !audioUpSub) viaNotify = false;
    if (viaNotify) flags |= IMG_FLAG_NOTIFY;
    img_header_t h = {2, flags, shot.id, (uint32_t)shot.len, crc32_update(0, shot.jpeg, shot.len), shot.width, shot.height};
    uint8_t hdr[IMG_HDR_V2_LEN];
    img_header_pack(&h, hdr);
    uint32_t t0 = millis();
    bool ok = indicateAndWait(controlChar, hdr, sizeof hdr);
    Serial.printf("[BLE] image %u header sent: %lu bytes, crc %08lx, %s -> %s\n", shot.id, (unsigned long)h.size,
                  (unsigned long)h.crc32, viaNotify ? "notify mode" : "indicate mode", ok ? "acknowledged" : "FAILED");
    size_t chunk = maxPayload();
    if (viaNotify) chunk -= AUDIO_HDR_LEN;
    size_t sent = 0, packets = 0;
    uint16_t retries = 0;
    uint8_t frame[256];
    audio_header_t ah = {STREAM_IMAGE, AUDIO_FLAG_START, 0, 0, 0, AUDIO_CODEC_RAW};
    while (ok && sent < shot.len) {
        if (abortImage) {
            Serial.printf("[BLE] image %u aborted by phone after %u bytes\n", shot.id, (unsigned)sent);
            uint8_t p[3]; put_u16(p, shot.id); p[2] = 0;
            sendEvent(EVT_IMAGE_ABORTED, p, 3);
            return false;
        }
        size_t n = min(chunk, shot.len - sent);
        if (viaNotify) {
            if (sent + n >= shot.len) ah.flags |= AUDIO_FLAG_END;
            audio_header_pack(&ah, frame);
            memcpy(frame + AUDIO_HDR_LEN, shot.jpeg + sent, n);
            ok = notifyAudio(frame, AUDIO_HDR_LEN + n, &retries);
            ah.seq++;
            ah.flags = 0;
        } else {
            ok = indicateAndWait(imageChar, shot.jpeg + sent, n);
        }
        if (ok) { sent += n; packets++; }
    }
    uint32_t ms = millis() - t0;
    if (ok) {
        Serial.printf("[BLE] image sent: %u bytes in %u packets of <=%u B, %lu ms (%.1f KB/s)%s\n",
                      (unsigned)sent, (unsigned)packets, (unsigned)chunk, (unsigned long)ms,
                      ms ? sent / 1.024 / ms : 0.0, viaNotify ? ", notify mode" : "");
        if (retries) Serial.printf("[BLE] (%u out-of-buffer retries)\n", retries);
    } else {
        Serial.printf("[BLE] transfer ABORTED after %u of %u bytes (%lu ms)\n", (unsigned)sent, (unsigned)shot.len, (unsigned long)ms);
    }
    return ok;
}

size_t pollCommand(uint8_t* buf, size_t cap) {
    Cmd c;
    if (xQueueReceive(cmdQ, &c, 0) != pdTRUE) return 0;
    size_t n = min((size_t)c.len, cap);
    memcpy(buf, c.data, n);
    return n;
}

void requestImageAbort() { abortImage = true; }

void reset() {
    if (isConnected && connHandle != BLE_HS_CONN_HANDLE_NONE) {
        Serial.println("[BLE] resetting the connection so the phone can reconnect quickly");
        server->disconnect(connHandle);
    }
}

void setDataLength(uint16_t octets) {
    if (isConnected && connHandle != BLE_HS_CONN_HANDLE_NONE) {
        server->setDataLen(connHandle, octets);
        Serial.printf("[BLE] requested LL data length %u\n", octets);
    }
}

